CREATE TYPE public.org_action AS ENUM ('consultar','crear','editar','eliminar','aprobar','exportar','administrar','auditar');
CREATE TYPE public.org_scope AS ENUM ('global','departamento','propio');
ALTER TABLE public.departments ADD COLUMN parent_id uuid REFERENCES public.departments(id) ON DELETE RESTRICT, ADD COLUMN head_user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL, ADD COLUMN is_active boolean NOT NULL DEFAULT true, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(), ADD CONSTRAINT departments_no_self_parent CHECK (parent_id IS NULL OR parent_id <> id);
CREATE TABLE public.org_resources (code text PRIMARY KEY CHECK(code ~ '^[a-z_]{3,40}$'), name text NOT NULL, description text NOT NULL DEFAULT '', allowed_actions public.org_action[] NOT NULL, allowed_scopes public.org_scope[] NOT NULL, sort_order int NOT NULL DEFAULT 0);
GRANT SELECT ON public.org_resources TO authenticated; GRANT ALL ON public.org_resources TO service_role; ALTER TABLE public.org_resources ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),resource text NOT NULL REFERENCES public.org_resources(code) ON DELETE CASCADE,action public.org_action NOT NULL,scope public.org_scope NOT NULL,is_sensitive boolean NOT NULL DEFAULT false,UNIQUE(resource,action,scope));
GRANT SELECT ON public.org_permissions TO authenticated; GRANT ALL ON public.org_permissions TO service_role; ALTER TABLE public.org_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code ~ '^[a-z0-9_]{3,50}$'),name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 120),description text NOT NULL DEFAULT '' CHECK(char_length(description)<=600),is_system boolean NOT NULL DEFAULT false,is_privileged boolean NOT NULL DEFAULT false,is_active boolean NOT NULL DEFAULT true,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.org_roles TO authenticated; GRANT ALL ON public.org_roles TO service_role; ALTER TABLE public.org_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_role_permissions (role_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES public.org_permissions(id) ON DELETE CASCADE,require_mfa boolean NOT NULL DEFAULT false,granted_by uuid,granted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(role_id,permission_id));
GRANT SELECT ON public.org_role_permissions TO authenticated; GRANT ALL ON public.org_role_permissions TO service_role; ALTER TABLE public.org_role_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code ~ '^[a-z0-9_]{2,50}$'),name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 120),description text NOT NULL DEFAULT '' CHECK(char_length(description)<=600),department_id uuid REFERENCES public.departments(id) ON DELETE RESTRICT,reports_to_id uuid REFERENCES public.org_positions(id) ON DELETE RESTRICT,responsibilities text[] NOT NULL DEFAULT '{}',is_external boolean NOT NULL DEFAULT false,is_active boolean NOT NULL DEFAULT true,sort_order int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(reports_to_id IS NULL OR reports_to_id<>id));
GRANT SELECT ON public.org_positions TO authenticated; GRANT ALL ON public.org_positions TO service_role; ALTER TABLE public.org_positions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_position_roles (position_id uuid NOT NULL REFERENCES public.org_positions(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE CASCADE,PRIMARY KEY(position_id,role_id));
GRANT SELECT ON public.org_position_roles TO authenticated; GRANT ALL ON public.org_position_roles TO service_role; ALTER TABLE public.org_position_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_user_positions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,position_id uuid NOT NULL REFERENCES public.org_positions(id) ON DELETE RESTRICT,department_id uuid REFERENCES public.departments(id),is_primary boolean NOT NULL DEFAULT false,starts_at date NOT NULL DEFAULT current_date,ends_at date,ended_at timestamptz,end_reason text,assigned_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.org_user_positions TO authenticated; GRANT ALL ON public.org_user_positions TO service_role; ALTER TABLE public.org_user_positions ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX org_user_positions_active_uq ON public.org_user_positions(user_id,position_id) WHERE ended_at IS NULL;
CREATE UNIQUE INDEX org_user_positions_primary_uq ON public.org_user_positions(user_id) WHERE is_primary AND ended_at IS NULL;
CREATE TABLE public.org_user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,role_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE RESTRICT,department_id uuid REFERENCES public.departments(id),justification text NOT NULL CHECK(char_length(justification)>=10),valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,granted_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,revoked_by uuid,revoke_reason text,CHECK(valid_until IS NULL OR valid_until>valid_from));
GRANT SELECT ON public.org_user_roles TO authenticated; GRANT ALL ON public.org_user_roles TO service_role; ALTER TABLE public.org_user_roles ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX org_user_roles_active_uq ON public.org_user_roles(user_id,role_id,coalesce(department_id,'00000000-0000-0000-0000-000000000000'::uuid)) WHERE revoked_at IS NULL;
CREATE INDEX org_user_roles_user_idx ON public.org_user_roles(user_id) WHERE revoked_at IS NULL;
CREATE TABLE public.org_user_denies (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES public.org_permissions(id) ON DELETE CASCADE,reason text NOT NULL CHECK(char_length(reason)>=5),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,permission_id));
GRANT SELECT ON public.org_user_denies TO authenticated; GRANT ALL ON public.org_user_denies TO service_role; ALTER TABLE public.org_user_denies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_sod_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),role_a_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE CASCADE,role_b_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE CASCADE,description text NOT NULL,severity text NOT NULL DEFAULT 'alta' CHECK(severity IN ('alta','media')),is_active boolean NOT NULL DEFAULT true,CHECK(role_a_id<>role_b_id));
GRANT SELECT ON public.org_sod_rules TO authenticated; GRANT ALL ON public.org_sod_rules TO service_role; ALTER TABLE public.org_sod_rules ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX org_sod_rules_pair_uq ON public.org_sod_rules(least(role_a_id,role_b_id),greatest(role_a_id,role_b_id));
CREATE TABLE public.org_sod_policies (code text PRIMARY KEY CHECK(code ~ '^[a-z_]{3,50}$'),name text NOT NULL,description text NOT NULL DEFAULT '',steps jsonb NOT NULL,amount_threshold numeric(14,2),enforced boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.org_sod_policies TO authenticated; GRANT ALL ON public.org_sod_policies TO service_role; ALTER TABLE public.org_sod_policies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_operation_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),policy_code text NOT NULL REFERENCES public.org_sod_policies(code),record_ref text NOT NULL CHECK(char_length(record_ref) BETWEEN 1 AND 120),step text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(policy_code,record_ref,step));
GRANT SELECT ON public.org_operation_steps TO authenticated; GRANT ALL ON public.org_operation_steps TO service_role; ALTER TABLE public.org_operation_steps ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_sod_exceptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('rol','operacion')),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,rule_id uuid REFERENCES public.org_sod_rules(id) ON DELETE CASCADE,policy_code text REFERENCES public.org_sod_policies(code),record_ref text,justification text NOT NULL CHECK(char_length(justification)>=20),approved_by uuid NOT NULL,starts_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz,revoked_by uuid,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='rol' AND rule_id IS NOT NULL AND policy_code IS NULL) OR (kind='operacion' AND policy_code IS NOT NULL AND rule_id IS NULL)),CHECK(expires_at>starts_at AND expires_at<=starts_at+interval '90 days'));
GRANT SELECT ON public.org_sod_exceptions TO authenticated; GRANT ALL ON public.org_sod_exceptions TO service_role; ALTER TABLE public.org_sod_exceptions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_change_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),actor_id uuid,actor_email text,action text NOT NULL,entity text NOT NULL,entity_id text,before_data jsonb,after_data jsonb,reason text,result text NOT NULL DEFAULT 'aplicado' CHECK(result IN ('aplicado','denegado')));
GRANT SELECT ON public.org_change_log TO authenticated; GRANT ALL ON public.org_change_log TO service_role; ALTER TABLE public.org_change_log ENABLE ROW LEVEL SECURITY;
CREATE INDEX org_change_log_created_idx ON public.org_change_log(created_at DESC);
CREATE INDEX org_change_log_actor_created_idx ON public.org_change_log(actor_id,created_at);
CREATE TABLE public.org_authz_config (id int PRIMARY KEY DEFAULT 1 CHECK(id=1),mode text NOT NULL DEFAULT 'legacy' CHECK(mode IN ('legacy','shadow','union','org')),enforcement_unlocked boolean NOT NULL DEFAULT false,require_mfa_admin boolean NOT NULL DEFAULT false,updated_by uuid,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.org_authz_config TO service_role; ALTER TABLE public.org_authz_config ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_legacy_map (legacy_perm public.iris_permission PRIMARY KEY,resource text REFERENCES public.org_resources(code),action public.org_action,status text NOT NULL CHECK(status IN ('equivalente','sin_equivalencia')),note text NOT NULL DEFAULT '',CHECK((status='equivalente')=(resource IS NOT NULL AND action IS NOT NULL)));
GRANT SELECT ON public.org_legacy_map TO authenticated; GRANT ALL ON public.org_legacy_map TO service_role; ALTER TABLE public.org_legacy_map ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.org_shadow_decisions (user_id uuid NOT NULL,perm public.iris_permission NOT NULL,legacy_result boolean NOT NULL,org_result boolean NOT NULL,hits bigint NOT NULL DEFAULT 1,first_seen timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,perm,legacy_result,org_result));
GRANT ALL ON public.org_shadow_decisions TO service_role; ALTER TABLE public.org_shadow_decisions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.org_block_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN RAISE EXCEPTION 'La evidencia de auditoría es inmutable' USING errcode='42501'; END $$;
REVOKE ALL ON FUNCTION public.org_block_mutation() FROM public,anon,authenticated;
CREATE TRIGGER org_change_log_immutable BEFORE UPDATE OR DELETE ON public.org_change_log FOR EACH ROW EXECUTE FUNCTION public.org_block_mutation();
CREATE TRIGGER org_change_log_no_truncate BEFORE TRUNCATE ON public.org_change_log FOR EACH STATEMENT EXECUTE FUNCTION public.org_block_mutation();
CREATE TRIGGER org_operation_steps_immutable BEFORE UPDATE OR DELETE ON public.org_operation_steps FOR EACH ROW EXECUTE FUNCTION public.org_block_mutation();
CREATE FUNCTION public.org_guard_department_cycle() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN PERFORM pg_advisory_xact_lock(170012); IF new.parent_id IS NOT NULL AND EXISTS(WITH RECURSIVE up AS (SELECT id,parent_id FROM public.departments WHERE id=new.parent_id UNION SELECT d.id,d.parent_id FROM public.departments d JOIN up ON d.id=up.parent_id) SELECT 1 FROM up WHERE id=new.id) THEN RAISE EXCEPTION 'La jerarquía de departamentos no puede ser circular'; END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.org_guard_department_cycle() FROM public,anon,authenticated;
CREATE TRIGGER org_department_cycle BEFORE INSERT OR UPDATE OF parent_id ON public.departments FOR EACH ROW EXECUTE FUNCTION public.org_guard_department_cycle();
CREATE FUNCTION public.org_guard_position_cycle() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN PERFORM pg_advisory_xact_lock(170013); IF new.reports_to_id IS NOT NULL AND EXISTS(WITH RECURSIVE up AS (SELECT id,reports_to_id FROM public.org_positions WHERE id=new.reports_to_id UNION SELECT p.id,p.reports_to_id FROM public.org_positions p JOIN up ON p.id=up.reports_to_id) SELECT 1 FROM up WHERE id=new.id) THEN RAISE EXCEPTION 'La jerarquía de cargos no puede ser circular'; END IF; RETURN new; END $$;
REVOKE ALL ON FUNCTION public.org_guard_position_cycle() FROM public,anon,authenticated;
CREATE TRIGGER org_position_cycle BEFORE INSERT OR UPDATE OF reports_to_id ON public.org_positions FOR EACH ROW EXECUTE FUNCTION public.org_guard_position_cycle();